def find_block(g):
    rs=[r for r in range(len(g)) for c in range(len(g[0])) if g[r][c]==3]
    cs=[c for r in range(len(g)) for c in range(len(g[0])) if g[r][c]==3]
    return min(rs),min(cs),max(rs),max(cs)

def transform(g):
    r0,c0,r1,c1=find_block(g)
    R=rot180(g); H,W=len(g),len(g[0])
    return [row[c0:c0+(c1-c0+1)] for row in R[H-1-r1:H-1-r0+1]]
